<script type="text/javascript">
  $(document).ready(function(){
    $('.n-dialog__close, .n-button--default-type').click(function () {
        $('.addupdate').hide();
       })
    
    $('.delete-button').click(function(e){
        e.preventDefault();
        
        var userId = $(this).attr('id');
        
        Swal.fire({
            title: 'Are you sure?',
            text: 'You won\'t be able to revert this!',
            icon: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#d33',
            cancelButtonColor: '#3085d6',
            confirmButtonText: 'Yes, delete it!'
        }).then((result) => {
            if (result.isConfirmed) {
                // If confirmed, proceed with delete action
                 $.ajax({
                    type: "POST",
                    url: "<?php echo base_url('member/delete_grade'); ?>",
                    data: {userId: userId},
                    success: function(response){
                      $('tbody #'+userId).remove();
                        Swal.fire({
                            icon: 'success',
                            title: 'Success!',
                            text: response.trim(),
                            showConfirmButton: false,
                            timer: 2000 // Automatically close after 1.5 seconds
                          });

                    },
                    error: function(xhr, status, error){
                        // Handle error
                        console.error(xhr.responseText);
                    }
                });
            }
        });
    });
});

 

        $(document).ready(function() {
         

          $('#ok').on('click', function(event) {
                event.preventDefault();
                
                // Get form data
                var formData = $('#updateForm').serialize();

                // AJAX request
                $.ajax({
                    url: 'member/update_grade_user', // Update with your controller method URL
                    type: 'POST',
                    data: formData,
                    dataType: 'json',
                    success: function(response) {
                       $('.addupdate').hide();
                         Swal.fire({
                            icon: 'success',
                            title: 'Success!',
                            text: response.message,
                            showConfirmButton: false,
                            timer: 2000 // Automatically close after 1.5 seconds
                          });
                           var ids = $('.idds').val();
                          $('#'+ids+' .upname').text($('#name').val());
                          $('#'+ids+' .upcommissionRate').text($('#commissionRate').val());
                          $('#'+ids+' .upcommissionPercentageOrder').text($('#commissionPercentageOrder').val());
                          $('#'+ids+' .upminimumBalanceLimit').text($('#minimumBalanceLimit').val());
                          $('#'+ids+' .upminimumWithdrawLimit').text($('#minimumWithdrawLimit').val());
                          $('#'+ids+' .uporderReciveLimit').text($('#orderReciveLimit').val());
                          $('#'+ids+' .upwithdrawLimit').text($('#withdrawLimit').val());
                          $('#'+ids+' .upmaxWithdrawLimit').text($('#maxWithdrawLimit').val());
                    },
                    error: function(xhr, status, error) {
                        // Handle error response
                        console.error(xhr.responseText);
                        alert('Error updating data. Please try again.');
                    }
                });
            });
            $('.edit-user').on('click', function() {
               
                var userId = $(this).attr('id');
                $.ajax({
                    url: 'member/get_grade_data/' + userId,
                    type: 'GET',
                    dataType: 'json',
                    success: function(response) {
                        $('.addupdate').show();
                        $.each(response, function(index, user) {
                        $('#name').val(user.name);
                        $('#ordersGrabbed').val(user.ordersGrabbed);
                        $('#commissionRate').val(user.commissionRate);
                        $('#commissionPercentageOrder').val(user.commissionPercentageOrder);
                        $('#minimumBalanceLimit ').val(user.minimumBalanceLimit );
                        $('#orderReciveLimit').val(user.orderReciveLimit);
                        $('#withdrawLimit').val(user.withdrawLimit);
                        $('#minimumWithdrawLimit').val(user.minimumWithdrawLimit);
                        $('#maxWithdrawLimit').val(user.maxWithdrawLimit);
                        $('#withdrawFee').val(user.withdrawFee);
                        $('.idds').val(user.id);
                    });
                  }
              });
            });
            
          });

  
</script>



